module.exports = "<div style=\"padding: 0 10px 10px 10px;\">\n  <div class=\"uk-flex uk-flex-center\">\n    <h2>{{ titulo_pagina }}</h2>\n  </div>\n\n  <div class=\"uk-flex uk-flex-center\">\n    <ul class=\"uk-subnav uk-subnav-pill\">\n        <li>\n          <a [ngClass]=\"{'btn-selecionado' : filtro.tipo == 'cadastrador', \n          'btn-nao-selecionado' : filtro.tipo != 'cadastrador'}\"\n          (click) = \"selecionarTipo('cadastrador');\">Usuário</a>\n        </li>\n        <li>\n          <a [ngClass]=\"{'btn-selecionado' : filtro.tipo == 'competidor', \n          'btn-nao-selecionado' : filtro.tipo != 'competidor'}\"\n          (click) = \"selecionarTipo('competidor');\">Competidor</a>\n        </li>\n    </ul>\n  </div>\n\n  <div class=\"uk-flex uk-flex-center\">\n    <input class=\"uk-input uk-width-1-4@s uk-margin\" type=\"text\" \n    placeholder=\"Procurar\"\n    (keyup)=\"filtroUsuario($event.target.value)\">\n  </div>\n\n  <div *ngIf=\"financeiros.length > 0 && (utilService.isAdm() || utilService.isOrganizador())\" class=\"uk-flex uk-flex-center\">\n    <div>\n      <button type=\"button\" id=\"exportar-financeiro\" class=\"uk-button uk-button-primary\"\n        (click)=\"financeiroXML()\" style=\"margin-bottom: 10px;\">\n        Baixar Excel\n    </button>\n    </div>\n  </div>\n\n  <div *ngIf=\"financeiros.length > 0\" class=\"uk-flex\" style=\"overflow: auto; width: 100%; height: 700px;\">\n    <table class=\"uk-table uk-table-striped\" style=\"font-size: 13px;\">\n      <thead>\n        <tr>\n            <th class=\"uk-table-shrink ajuste-padding\">\n              <strong class=\"th-config\">Número</strong>\n            </th>\n            <th class=\"uk-width-small ajuste-padding\">\n              <strong class=\"th-config\">Nome</strong>\n            </th>\n            <th class=\"uk-table-shrink ajuste-padding\">\n              <strong class=\"th-config\">Inscrições</strong>\n            </th>\n            <th class=\"uk-table-shrink ajuste-padding\">\n              <strong class=\"th-config\">Filiações</strong>\n            </th>\n            <th class=\"uk-width-small ajuste-padding\">\n              <strong class=\"th-config\">Custo</strong>\n            </th>\n            <th class=\"uk-width-small ajuste-padding\">\n              <strong class=\"th-config\">Pago</strong>\n            </th>\n            <th class=\"uk-width-small ajuste-padding\">\n              <strong class=\"th-config\">Saldo</strong>\n            </th>\n        </tr>\n    </thead>\n\n    <tbody>\n      <tr *ngFor=\"let financeiro of financeiros; let i = index\"\n        class=\"mouse-mao\"\n        (click)=\"buscaInscricaoCompetidor(financeiro.id_usuario, financeiro.nome);\"\n        href=\"#modal-sections\" uk-toggle>\n          <td \n           class=\"ajuste-padding\">\n            <strong>Número: </strong>\n            {{financeiro.id_usuario}}\n          </td>\n          <td class=\"ajuste-padding\" title=\"{{financeiro.nome}}\">\n            <strong>Competidor: </strong>\n            <span class=\"span-web\">{{utilService.reduzTexto(financeiro.nome, 20)}}</span>\n            <span class=\"span-mob\">{{utilService.reduzTexto(financeiro.nome, 26)}}</span>\n          </td>\n          <td class=\" ajuste-padding\">\n            <strong>Inscrições: </strong>\n            {{ financeiro.qtd_inscricoes }}\n          </td>\n          <td class=\"ajuste-padding\">\n            <strong>Filiações: </strong>\n            {{ financeiro.qtd_associacoes }}\n          </td>\n          <td class=\"ajuste-padding\">\n            <strong>Custo: </strong>\n            {{ financeiro.custo | currency:'BRL':'symbol' }}\n          </td>\n          <td class=\"ajuste-padding\">\n            <strong>Pago: </strong>\n            {{ financeiro.pago | currency:'BRL':'symbol' }}\n          </td>\n          <td class=\"ajuste-padding\">\n            <strong>Saldo: </strong>\n            {{ financeiro.saldo | currency:'BRL':'symbol' }}\n          </td>\n      </tr>\n      <tr>\n        <td class=\"uk-width-small ajuste-padding\"><span class=\"total\">TOTAL:</span></td>\n        <td *ngIf=\"!utilService.isMobile()\" class=\"uk-width-small ajuste-padding\"></td>\n        <td  class=\"uk-width-small ajuste-padding\">\n          <strong>Inscrições:</strong>\n          {{ resultado?.totalInscricoes }}\n        </td>\n        <td  class=\"uk-width-small ajuste-padding\">\n          <strong>Filiações:</strong>\n          {{ resultado?.totalAssociacoes }}\n        </td>\n        <td class=\"uk-width-small ajuste-padding\">\n          <strong>Custo:</strong> \n          {{ resultado?.totalCusto | currency:'BRL':'symbol' }}\n        </td>\n        <td class=\"uk-width-small ajuste-padding\">\n          <strong>Pago:</strong> \n          {{ resultado?.totalPago | currency:'BRL':'symbol' }}\n        </td>\n        <td  class=\"uk-width-small ajuste-padding\">\n          <strong>Saldo:</strong> \n          {{ resultado?.totalSaldo | currency:'BRL':'symbol' }}\n        </td>\n      </tr>\n    </tbody>\n\n    </table>\n\n  </div>\n\n  <div *ngIf=\"financeiros.length == 0\" \n  class=\"uk-flex uk-flex-center\"\n  style=\"margin-top: 35px;\">\n    <h3>Nenhuma inscrição no evento</h3>\n  </div>\n\n  <div id=\"modal-sections\" class=\"uk-modal-container\" uk-modal>\n    <div class=\"uk-modal-dialog\">\n        <button class=\"uk-modal-close-default\" type=\"button\" uk-close  style=\"color: white;\"></button>\n        <div class=\"uk-modal-header\" style=\"color: white; background: #C11414 !important;\">\n            <h2 *ngIf=\"inscricoes.length <= 1\" class=\"uk-modal-title\" style=\"color: white; margin: 0px\">Inscrição</h2>\n            <h2 *ngIf=\"inscricoes.length > 1\" class=\"uk-modal-title\" style=\"color: white; margin: 0px\">Inscrições</h2>\n            <h6 class=\"uk-modal-title\" style=\"color:white; margin: 0px; font-size: 20px;\">\n              {{ filtro.tipo | titlecase }} - {{ nomeCompetidor | titlecase }}\n            </h6>\n        </div>\n        <div class=\"uk-modal-body\">\n          <div style=\"overflow: auto; width: 100%; height: 300px; padding: 5px;\">\n            <table class=\"uk-table uk-table-striped\" style=\"font-size: 13px;\">\n              <thead>\n                <tr>\n                  <th class=\"uk-table-shrink config-th-modal\">\n                    <strong class=\"th-config\">Inscrição</strong>\n                  </th>\n\n                  <th *ngIf=\"utilService.isMobile()\" class=\"uk-table-shrink config-th-modal\">\n                    <strong class=\"th-config\">Nº</strong>\n                  </th>\n\n                  <th class=\"uk-width-small config-th-modal\">\n                    <strong class=\"th-config\">Nome</strong>\n                  </th>\n                  <th class=\"uk-width-small config-th-modal\">\n                    <strong class=\"th-config\">Cavalo</strong>\n                  </th>\n                  <th class=\"uk-width-small config-th-modal\">\n                    <strong class=\"th-config\">Usuário</strong>\n                  </th>\n                  <th class=\"uk-width-small config-th-modal\">\n                    <strong class=\"th-config\">Divisão</strong>\n                  </th>\n                  <th class=\"uk-width-small config-th-modal\">\n                    <strong class=\"th-config\">Valor</strong>\n                  </th>\n                  <th class=\"uk-width-small config-th-modal\">\n                    <strong class=\"th-config\">Pago</strong>\n                  </th>\n                  <th class=\"uk-width-small config-th-modal\">\n                    <strong class=\"th-config\">Pagamento</strong>\n                  </th>\n                </tr>\n              </thead>\n        \n              <tbody>\n                <tr *ngFor=\"let inscricao of inscricoes;\" >\n                  <td class=\"ajuste-padding\">\n                    <div \n                      [ngClass]=\"{'margin-insc' : inscricao.competidores.length > 1,\n                       'sem-margin-insc' : inscricao.competidores.length == 1}\">\n                      <span\n                      [ngClass]=\"{'padding-insc' : !utilService.isMobile(),\n                       'sem-padding-insc' : utilService.isMobile()}\">\n                        <strong>Número: </strong>\n                        {{ inscricao.id_inscricao }}</span>\n                    </div>\n                  </td>\n  \n                  <td class=\"ajuste-padding\">\n                   <div *ngFor=\"let competidor of inscricao.competidores; let i = index\">\n                     <span title=\"{{competidor.nome_competidor}}\">\n                        <strong>Competidor \n                          <span *ngIf=\"inscricao.competidores.length > 1\">{{i+1}}</span>:\n                        </strong>\n                        <span class=\"span-web\">{{ utilService.reduzTexto(competidor.nome_competidor, 15)}}</span>\n                        <span class=\"span-mob\">{{ utilService.reduzTexto(competidor.nome_competidor, 20)}}</span>\n                      </span>\n                     <hr *ngIf=\"(i + 1) < inscricao.competidores.length\"\n                     class=\"hr\">\n                   </div>\n                  </td>\n  \n                  <td class=\"ajuste-padding\">\n                    <div *ngFor=\"let competidor of inscricao.competidores; let i = index\">\n                      <span title=\"{{competidor.nome_cavalo}}\">\n                        <strong>Cavalo \n                          <span *ngIf=\"inscricao.competidores.length > 1\">{{i+1}}</span>:\n                        </strong>\n                        <span class=\"span-web\">{{ utilService.reduzTexto(competidor.nome_cavalo, 15) }}</span>\n                        <span class=\"span-mob\">{{ utilService.reduzTexto(competidor.nome_cavalo, 20) }}</span>\n                      </span>\n                      <hr *ngIf=\"(i + 1) < inscricao.competidores.length\"\n                      class=\"hr\">\n                    </div>\n                 </td>\n  \n                  <td class=\"ajuste-padding\">\n                    <div [ngClass]=\"{'margin-insc' : inscricao.competidores.length > 1,\n                      'sem-margin-insc' : inscricao.competidores.length == 1}\">\n                      <span title=\"{{inscricao.cadastrador.nome}}\">\n                        <strong>Usuário: </strong>\n                        <span class=\"span-web\"> {{ utilService.reduzTexto(inscricao.cadastrador.nome, 15) }}</span>\n                        <span class=\"span-mob\"> {{ utilService.reduzTexto(inscricao.cadastrador.nome, 20) }}</span>\n                      </span>\n                    </div>\n                 </td>\n  \n                  <td class=\"ajuste-padding\">\n                    <div [ngClass]=\"{'margin-insc' : inscricao.competidores.length > 1,\n                      'sem-margin-insc' : inscricao.competidores.length == 1}\">\n                      <span title=\"{{inscricao.prova.nome}}\">\n                        <strong>Divisão: </strong>\n                        <span class=\"span-web\">{{ utilService.reduzTexto(inscricao.prova.nome, 26) }}</span>\n                        <span class=\"span-mob\">{{ utilService.reduzTexto(inscricao.prova.nome, 30) }}</span>\n                      </span>\n                    </div>\n                  </td>\n\n                  <td class=\"ajuste-padding\">\n                    <div *ngFor=\"let competidor of inscricao.competidores; let i = index\"\n                      class=\"div-valor\">\n                      <span>\n                        <strong>Valor Competidor\n                          <span *ngIf=\"inscricao.competidores.length > 1\">{{i+1}}</span>:\n                        </strong>\n                        <span class=\"span-web\">{{ competidor.custo | currency:'BRL':'symbol' }}</span>\n                        <span class=\"span-mob\">{{ competidor.custo | currency:'BRL':'symbol' }}</span>\n                      </span>\n                      <hr *ngIf=\"(i + 1) < inscricao.competidores.length\"\n                      class=\"hr\">\n                    </div>\n                  </td>\n\n                  <td class=\"ajuste-padding\">\n                    <div *ngFor=\"let competidor of inscricao.competidores; let i = index\"\n                      class=\"div-valor\">\n                      <span>\n                        <strong>Pago Competidor\n                          <span *ngIf=\"inscricao.competidores.length > 1\">{{i+1}}</span>:\n                        </strong>\n                        <span class=\"span-web\">{{ competidor.pago | currency:'BRL':'symbol' }}</span>\n                        <span class=\"span-mob\">{{ competidor.pago | currency:'BRL':'symbol' }}</span>\n                      </span>\n                      <hr *ngIf=\"(i + 1) < inscricao.competidores.length\"\n                      class=\"hr\">\n                    </div>\n                  </td>\n\n                  <td class=\"ajuste-padding\">\n                    <div *ngFor=\"let competidor of inscricao.competidores; let i = index\"\n                      class=\"div-valor\">\n                      <span>\n                        <strong>Editar Pagamento Comp\n                          <span *ngIf=\"inscricao.competidores.length > 1\">{{i+1}}</span>:\n                        </strong>\n                        <span class=\"span-web\" style=\"padding-left: 5px;\">\n                          <input id = \"checkboxInput{{competidor.inscricao_competidor.id_inscricao_competidor}}\"\n                          type=\"checkbox\" class=\"uk-checkbox\"\n                          [checked] = \"competidor.inscricao_competidor.inscricao_paga\" \n                          uk-tooltip=\"title: Efetuar ou remove o pagamento da inscrição\"\n                          (click) = \"pagamentoCompetidor(competidor.inscricao_competidor)\">\n                        </span>\n                        <span class=\"span-mob\">\n                          <input id = \"checkboxInput{{competidor.inscricao_competidor.id_inscricao_competidor}}\" \n                          type = \"checkbox\" class=\"uk-checkbox\"\n                          [checked] = \"competidor.inscricao_competidor.inscricao_paga\" \n                          uk-tooltip=\"title: Efetuar ou remove o pagamento da inscrição\"\n                          (click) = \"pagamentoCompetidor(competidor.inscricao_competidor)\">\n                          <span *ngIf=\"competidor.inscricao_competidor.inscricao_paga\"> Pago</span>\n                          <span *ngIf=\"!competidor.inscricao_competidor.inscricao_paga\"> Não Pago</span>\n                        </span>\n                      </span>\n                      <hr *ngIf=\"(i + 1) < inscricao.competidores.length\"\n                      class=\"hr\">\n                    </div>\n                  </td>\n  \n                </tr>\n  \n              </tbody>\n        \n            </table>\n          </div>\n\n          <div class=\"uk-flex uk-inline\" style=\"margin-top: 10px;\">\n            <div *ngIf=\"filtro.tipo || valoresInscricoes\" class=\"uk-margin-right card\">\n              <h4 class=\"h4-valores\">Inscrições</h4>\n              <span *ngIf=\"valoresInscricoes && valoresInscricoes.custoTotal\" class=\"uk-text-left\" \n              style=\"color: black;\">\n              <span style=\"font-weight: bolder\">Custo das inscrições:</span> {{ valoresInscricoes.custoTotal | currency:'BRL':'symbol' }}\n              </span>\n              <br *ngIf=\"valoresInscricoes && valoresInscricoes.custoTotal && filtro.tipo == 'competidor'\">\n              <span *ngIf=\"filtro.tipo == 'competidor'\" class=\"uk-text-left\" style=\"color: black;\">\n                <span style=\"font-weight: bolder\">Custo individual:</span> {{ custoIndividual | currency:'BRL':'symbol'}}\n              </span>\n              <br *ngIf=\"filtro.tipo == 'competidor' || filtro.tipo == 'cadastrador'\">\n              <span *ngIf=\"filtro.tipo == 'competidor'\" class=\"uk-text-left\" style=\"color: black;\">\n                <span style=\"font-weight: bolder\">Pago individual:</span> {{ pagoIndividual | currency:'BRL':'symbol'}}\n              </span>\n              <span *ngIf=\"filtro.tipo == 'cadastrador'\" class=\"uk-text-left\" style=\"color: black;\">\n                <span style=\"font-weight: bolder\">Pago:</span> {{ pagoIndividual | currency:'BRL':'symbol'}}\n              </span>\n              <br>\n              <span class=\"uk-text-left\" style=\"color: black;\">\n                <span *ngIf=\"filtro.tipo == 'competidor'\" style=\"font-weight: bolder\">Saldo individual:</span>\n                <span *ngIf=\"filtro.tipo == 'cadastrador'\" style=\"font-weight: bolder\">Saldo:</span> {{ saldoIndividual | currency:'BRL':'symbol'}}\n              </span>\n              <br>\n              <span class=\"uk-text-left\" style=\"color: black;\">\n                <span style=\"font-weight: bolder\" title=\"Saldo das inscrição(ões) mais o saldo da(s) filiação(ões)\">Saldo Total:</span>{{ saldoTotal | currency:'BRL':'symbol'}}\n              </span>\n            </div>\n            <div *ngIf=\"valoresAssociacao\" class=\"uk-margin-right card\">\n              <h4 class=\"h4-valores\">Filiações</h4>\n              <span class=\"uk-text-left\" \n              style=\"color: black;\">\n              <span style=\"font-weight: bolder\">Custo:</span> {{ valoresAssociacao.custoTotal | currency:'BRL':'symbol' }}\n              </span>\n              <br>\n              <span class=\"uk-text-left\" style=\"color: black;\">\n                <span style=\"font-weight: bolder\">Pago:</span> {{ valoresAssociacao.pagoTotal | currency:'BRL':'symbol'}}\n              </span>\n              <br>\n              <span class=\"uk-text-left\" style=\"color: black;\">\n                <span style=\"font-weight: bolder\">Saldo:</span> {{ valoresAssociacao.saldoTotal | currency:'BRL':'symbol'}}\n              </span>\n            </div>\n          </div>\n          <div class=\"uk-flex\">\n            <div>\n              <button class=\"uk-button uk-button-primary margin-top\"\n               (click)=\"efetuarPagamentos();\">Pagar Inscrição(ões)</button>\n               <br>\n              <button class=\"uk-button uk-button-danger margin-top\"\n               (click)=\"removerPagamentos();\">Remover pagamento Inscrição(ões)</button>\n               <br>\n              <button *ngIf=\"associacoes.length > 0 && valoresAssociacao.saldoTotal && valoresAssociacao.saldoTotal < 0\" class=\"uk-button uk-button-primary margin-top\"\n              (click)=\"pagarFiliacao();\">Pagar Filiação(ões)</button>\n              <br *ngIf=\"associacoes.length > 0 && valoresAssociacao.saldoTotal && valoresAssociacao.saldoTotal < 0\">\n              <button *ngIf=\"associacoes.length > 0 && valoresAssociacao.pagoTotal != 0\" class=\"uk-button uk-button-primary margin-top\"\n                (click)=\"removerPagamentoFiliacao();\">Remover pagamento Filiação(ões)</button>\n            </div>\n          </div>\n        </div>\n\n        <div *ngIf=\"valoresAssociacao && valoresAssociacao.saldoTotal < 0\"\n         class=\"uk-modal-footer\">\n            <span *ngIf=\"valoresAssociacao.saldoTotal && valoresAssociacao.saldoTotal < 0\" \n              class=\"uk-text-left\" style=\"color: black; font-weight: bolder\">\n              Este {{ filtro.tipo | lowercase }} possui filiação(ões) a pagar.\n               Saldo: {{ valoresAssociacao.saldoTotal | currency:'BRL':'symbol' }}\n            </span>\n        </div>\n        \n        <div *ngIf=\"!valoresAssociacao && !valoresInscricoes\" \n          class=\"uk-modal-footer  uk-text-right\">\n            <button \n              class=\"uk-button uk-button-default uk-button-danger uk-modal-close\"\n            type=\"button\">Fechar</button>\n        </div>\n    </div>\n  </div>\n\n</div>\n\n"

