    CadastroEventoComponent.prototype.getDivisoes = function () {
        var _this = this;
        this.divisaoService.buscaTodos().subscribe(function (divisoes) {
            _this.divisoes = divisoes.sort(function (a, b) {
                return a.nome > b.nome ? 1 : a.nome < b.nome ? -1 : 0;
            });
            _this.divisoes_evento.forEach(function (divisao_evento) {
                _this.divisoes.forEach(function (divisao) {
                    if (divisao_evento.id_divisao == divisao.id_divisao) {
                        _this.divisoes.splice(_this.divisoes.indexOf(divisao), 1);
                    }
                });
            });
        });
    };
    CadastroEventoComponent.prototype.pegaDivisaoSelecionada = function (event) {
        this.id_divisaoSelecionada = parseInt(event.target.value);
    };
    CadastroEventoComponent.prototype.adicionaDivisao = function () {
        var _this = this;
        if (this.id_divisaoSelecionada != null) {
            if (this.divisoes_evento.find(function (divisao) { return divisao.id_divisao == _this.id_divisaoSelecionada; })) {
                this.utilService.mensagemErro('Prova já inserida');
            }
            else {
                this.divisaoService.buscaPorId(this.id_divisaoSelecionada).subscribe(function (divisao) {
                    _this.divisoes_evento.push(divisao);
                });
            }
        }
        else {
            this.utilService.mensagemErro('Selecione alguma prova');
        }
    };
    CadastroEventoComponent.prototype.removeDivisaoEvento = function (divisao) {
        this.divisoes_evento.splice(this.divisoes_evento.indexOf(divisao), 1);
        this.divisoes_evento.push(divisao);
    };
    CadastroEventoComponent.prototype.redirecionaCriaDivisao = function () {
        this.evento.divisoes = this.divisoes_evento;
        this.eventoService.setEventoTemporario(this.evento);
        this.utilService.irPara(this.router, '/comum/cadastro-divisao/');
    };
    CadastroEventoComponent.prototype.selecionaOrganizador = function (id_organizador) {
        var _this = this;
        this.evento.id_organizador = Number(id_organizador);
        this.formCadastro.controls['id_organizador'].setValue(Number(id_organizador));
        this.organizadores.forEach(function (organizador) {
            if (id_organizador == organizador.id_usuario) {
                _this.evento.nome_organizador = organizador.nome;
            }
        });
        this.erro = false;
        this.organizadores = [];
    };
    CadastroEventoComponent.prototype.getOrganizadores = function () {
        var _this = this;
        this.usuarioService.buscaOrganizadores().subscribe(function (retorno) {
            _this.organizadores = retorno;
        });
    };
    CadastroEventoComponent.prototype.salvar = function () {
        if (this.formCadastro.invalid) {
            if (this.formCadastro.controls['id_organizador'].invalid) {
                this.erro = true;
            }
            this.utilService.destacarErros(this.formCadastro);
            return false;
        }
        var dataInicialEvento = this.utilService.converteNewData(this.evento.data_inicial);
        var dataFinalEvento = this.utilService.converteNewData(this.evento.data_final);
        var dataInicial = new Date(this.campeonato.data_inicial);
        var dataFinal = new Date(this.campeonato.data_final);
        if (dataInicialEvento.getTime() > dataFinalEvento.getTime()) {
            this.utilService.mensagemErro("A data final do evento não pode ser menor que a data inicial do evento.");
            return false;
        }
        if (dataInicialEvento.getTime() < dataInicial.getTime()) {
            this.utilService.mensagemErro("A data inicial do evento não pode ser menor que a data inicial do campeonato.");
            return false;
        }
        if (dataInicialEvento.getTime() > dataFinal.getTime()) {
            this.utilService.mensagemErro("A data inicial do evento não pode ser maior que a data final do campeonato.");
            return false;
        }
        this.requisicao();
    };
    CadastroEventoComponent.prototype.requisicao = function () {
        var _this = this;
        var mensagemConfirmacao = this.divisoes_evento.length == 0 ? 'Deseja realmente salvar um evento sem provas?'
            : 'Deseja realmente salvar o evento?';
        this.evento.regras = this.regras_evento;
        if (this.divisoes_evento.length != 0 && this.divisoes_evento_copia.length != 0) {
            var divi_1 = [];
            var control_1 = false;
            this.divisoes_evento_copia.forEach(function (copia) {
                _this.divisoes_evento.forEach(function (div) {
                    if (copia.nome == div.nome) {
                        control_1 = true;
                    }
                });
                if (control_1 == false) {
                    copia.status = 2;
                    divi_1.push(copia);
                }
                control_1 = false;
            });
            divi_1.forEach(function (d) {
                _this.divisoes_evento.push(d);
            });
        }
        this.atualizaDivisao();
        this.utilService.mensagemConfirmacao(mensagemConfirmacao, function (result) {
            if (result) {
                _this.requisicaoSalvar();
            }
        });
    };
