    CadastroEventoComponent.prototype.uploadImagem = function () {
        var bar = document.getElementById('js-progressbar');
        var uploadURL = this.eventoService.upload_imagem_api_url;
        var formCadastro = this;
        UIkit.upload('.js-upload', {
            url: uploadURL,
            multiple: false,
            mime: '.jpg, .png, .jpeg, .gif, .bmp, .tif, .tiff|image/*',
            loadStart: function (e) {
                bar.removeAttribute('hidden');
                bar.max = e.total;
                bar.value = e.loaded;
            },
            progress: function (e) {
                bar.max = e.total;
                bar.value = e.loaded;
            },
            loadEnd: function (e) {
                var response = JSON.parse(e.srcElement.response);
                formCadastro.atribuiValorImagem(response);
                bar.max = e.total;
                bar.value = e.loaded;
            },
            completeAll: function () {
                setTimeout(function () {
                    bar.setAttribute('hidden', 'hidden');
                }, 1000);
            },
            fail: function () {
                alert('Formato de arquivo não suportado');
            }
        });
    };
