module.exports = "<div class=\"uk-container container centralizado uk-width-2-3@m\">\n  <h3 class=\"uk-text-center\">Cavalos pendentes de moderação</h3>\n  <ul *ngIf=\"cavalos.length > 0\" class=\"accordion\" uk-accordion>\n      <li *ngFor=\"let cavalo of cavalos\" class=\"card uk-width-1-1\">\n          <a class=\"title uk-accordion-title\">\n              <div class=\"titulo uk-text-center\">\n                  <strong>{{cavalo.nome}}</strong>\n              </div>\n          </a>\n            <div class=\"div uk-accordion-content\">\n                <div class=\"uk-width-1-1@s uk-flex uk-flex-wrap\">\n                    <div class=\"card uk-width-3-5@s uk-padding-small uk-position-relative\">\n                        <span><strong>Data de Nascimento:</strong></span> {{cavalo?.nascimento | date: 'dd/MM/yyyy'}}<br>\n                        <span><strong>Sexo:</strong></span> {{utilService.getSexoCavalo(cavalo?.sexo_animal)}}<br>\n                        <span><strong>Registro:</strong></span> {{cavalo?.registro}}<br>\n                        <span><strong>Raça:</strong></span> {{cavalo?.raca}}<br>\n                        <span><strong>Cidade:</strong></span> {{cavalo?.cidade}}<br>\n                        <span *ngIf=\"cavalo.nome_proprietario && !cavalo.proprietario\"><strong>Nome Proprietário:</strong> {{cavalo?.nome_proprietario}}</span><br *ngIf=\"cavalo.nome_proprietario && !cavalo.proprietario\">\n                        <fieldset *ngIf=\"cavalo.proprietario\" class=\"correction\">\n                            <legend>Proprietário</legend>\n                            <span><strong>Nome:</strong></span> {{cavalo?.proprietario.nome}}<br>\n                            <span *ngIf=\"cavalo.proprietario.apelido\"><strong>Apelido:</strong> {{cavalo?.proprietario.apelido}}</span><br *ngIf=\"cavalo.proprietario.apelido\">\n                            <span><strong>Cidade:</strong></span> {{cavalo?.proprietario.cidade}}<br>\n                            <span><strong>E-mail:</strong></span> {{cavalo?.proprietario.email}}<br>\n                            <span><strong>Telefone:</strong></span> {{cavalo?.proprietario.telefone}}<br>\n                        </fieldset>\n                    </div>\n                    <div class=\"uk-width-2-5@s uk-padding uk-flex uk-flex-wrap\">\n                      <div class=\"uk-width-1-1@s uk-flex uk-flex-middle uk-flex-center\">\n                          <div class=\"uk-width-1-2@s uk-flex uk-flex-middle uk-flex-center\">\n                              <button type=\"button\" class=\"uk-button uk-button-primary uk-button\" (click)=\"aprovar(cavalo)\">Aceitar</button>\n                          </div>\n                          <div class=\"uk-width-1-2@s uk-flex uk-flex-middle uk-flex-center\">\n                              <button type=\"button\" class=\"uk-button uk-button-danger uk-button\" (click)=\"rejeitar(cavalo)\">Negar</button>\n                          </div>\n                      </div>\n                    </div>\n                </div>\n            </div>\n      </li>\n  </ul>\n  <div *ngIf=\"cavalos?.length == 0\" class=\"uk-text-center\">\n      <h1>Não há mais cavalos para avaliar</h1>\n  </div>\n</div>"

